#!/usr/bin/env python3
"""Emit results/tab_teacher_per_dataset.tex from the computed CSV."""
from __future__ import annotations
import sys
from pathlib import Path
import pandas as pd

REPO = Path(__file__).resolve().parents[1]
d = pd.read_csv(REPO/"results/tables/tab_teacher_per_dataset.csv")

def kb(b):
    return f"{b/1024:.1f}\\,KB" if b < 1024*1024 else f"{b/1024/1024:.2f}\\,MB"

lines = [
r"""% ============================================================
% tab_teacher_per_dataset.tex  --  generated by scripts/make_teacher_table.py
% Source: results/tab_teacher_per_dataset.csv
% Protocol: seed 42, the same test partitions and batching regime as Tables III/VI.
% Label: tab:dep:teacher     Requires: booktabs, multirow
% BACC/MCC/DR/FAR recomputed; footprint and latency joined from
% results/deployment/deployment_measurements.csv; energy = comparisons x 0.9 pJ.
% ============================================================
\begin{table*}[!t]
\centering
\caption{Per-dataset characteristics of the gradient-boosted teacher, as a
deployable detector, under the protocol of Tables~III and~VI (seed 42, identical
test partitions and batching). \emph{Full} is the cost-sensitive teacher used for
encoder construction; \emph{compact} is its validation-selected boosting-round
prefix, chosen without reference to test data. Footprint is the serialized model
in bytes, excluding the preprocessing metadata common to all systems. Energy
prices each tree comparison at the Horowitz accumulate cost of $0.9$\,pJ, a
subtract-and-branch belonging to that cost class; \emph{Rel.\ E} is the ratio to
Tree-to-Spike's SOP-priced arithmetic energy on the same dataset, so values below
unity indicate the ensemble performs less arithmetic than the spiking student.}
\label{tab:dep:teacher}
\small
\setlength{\tabcolsep}{4pt}
\begin{tabular}{llrrrrrrrr}
\toprule
Dataset & Arm & BACC & MCC & DR & FAR & Footprint & $p_{50}$ & $E_\mathrm{arith}$ & Rel.\ E \\
 & & (\%) & (\%) & (\%) & (\%) & & (ms) & (pJ) & \\
\midrule"""]

for ds, g in d.groupby("dataset", sort=False):
    nm = g.name.iloc[0]
    for i, (_, r) in enumerate(g.iterrows()):
        first = f"\\multirow{{2}}{{*}}{{{nm}}}" if i == 0 else ""
        lines.append(
            f"{first} & {r.arm} & {r.BACC:.2f} & {r.MCC:.2f} & {r.DR:.2f} & "
            f"{r.FAR:.2f} & {kb(r.bytes)} & {r.p50_ms:.3f} & {r.E_pJ:,.0f} & "
            f"{r.rel_E_vs_t2s:.2f}$\\times$ \\\\")
    lines.append(r"\addlinespace")

for arm in ("full", "compact"):
    g = d[d.arm == arm]
    lines.append(
        (r"\midrule " if arm == "full" else "") +
        f"\\textbf{{Mean}} & {arm} & {g.BACC.mean():.2f} & {g.MCC.mean():.2f} & "
        f"{g.DR.mean():.2f} & {g.FAR.mean():.2f} & {kb(g.bytes.mean())} & "
        f"{g.p50_ms.mean():.3f} & {g.E_pJ.mean():,.0f} & "
        f"{g.rel_E_vs_t2s.mean():.2f}$\\times$ \\\\")

lines.append(r"""\bottomrule
\end{tabular}
\end{table*}""")

out = REPO/"results/tables/tab_teacher_per_dataset.tex"
out.write_text("\n".join(lines) + "\n")
print(f"[wrote] {out} ({len(lines)} lines, {d.dataset.nunique()} datasets)")
